import "server-only";
import { getResend } from "@/lib/resend";
import type { EmailContent } from "@/emails/layout";
import { welcomeEmail } from "@/emails/welcome";
import { passwordResetEmail } from "@/emails/password-reset";

export type SendResult = { ok: true; id: string } | { ok: false; error: string };

function appUrl(path: string): string {
  return new URL(path, process.env.APP_URL ?? "http://localhost:3000").toString();
}

// Never throws: a failed email must not break the request that triggered it.
async function send(to: string, content: EmailContent, idempotencyKey?: string): Promise<SendResult> {
  const from = process.env.RESEND_FROM_EMAIL;
  if (!process.env.RESEND_API_KEY || !from) {
    console.warn(`[email] RESEND_API_KEY / RESEND_FROM_EMAIL not set; skipped "${content.subject}" to ${to}`);
    return { ok: false, error: "Email is not configured" };
  }

  try {
    const { data, error } = await getResend().emails.send(
      { from, to, subject: content.subject, html: content.html, text: content.text },
      idempotencyKey ? { idempotencyKey } : undefined,
    );
    if (error || !data) {
      console.error(`[email] Resend refused "${content.subject}" to ${to}:`, error);
      return { ok: false, error: error?.message ?? "Unknown Resend error" };
    }
    return { ok: true, id: data.id };
  } catch (err) {
    console.error(`[email] Failed to send "${content.subject}" to ${to}:`, err);
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}

export function sendWelcomeEmail(user: { id: string; email: string; name: string }): Promise<SendResult> {
  return send(
    user.email,
    welcomeEmail({ name: user.name, dashboardUrl: appUrl("/dashboard") }),
    `welcome/${user.id}`,
  );
}

export function sendPasswordResetEmail(
  user: { email: string; name: string },
  token: string,
  expiresInMinutes: number,
): Promise<SendResult> {
  const resetUrl = appUrl(`/reset-password?token=${encodeURIComponent(token)}`);
  return send(user.email, passwordResetEmail({ name: user.name, resetUrl, expiresInMinutes }));
}
